func:
// Two in-memory files and one path. A Buffer carries no name of its own, so msg.filename
// supplies one per position; the path in the middle needs no entry.
msg.payload = [
    Buffer.from('the first file'),
    '/tmp/second.jpg',
    Buffer.from('the third file'),
];
msg.filename = ['first.txt', undefined, 'third.txt'];
msg.caption = 'three at once';

return msg;
